def link(p,label,target):
 h=OxmlElement('w:hyperlink');h.set(qn('r:id'),p.part.relate_to(target,'http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink',is_external=True))
 r=OxmlElement('w:r');pr=OxmlElement('w:rPr');c=OxmlElement('w:color');c.set(qn('w:val'),'245A81');pr.append(c);r.append(pr);t=OxmlElement('w:t');t.text=label;r.append(t);h.append(r);p._p.append(h)
def p(d,s,style=None):return d.add_paragraph(s,style)
def page(d,s):
 q=d.add_heading(s,1);q.paragraph_format.page_break_before=True
def table(d,heads,rows,widths):
 t=d.add_table(rows=1,cols=len(heads));t.autofit=False
 for col,w in zip(t.columns,widths):col.width=Inches(w)
 for i,x in enumerate(heads):t.rows[0].cells[i].text=x
 for row in rows:
  for c,x in zip(t.add_row().cells,row):c.text=str(x)
 for ri,row in enumerate(t.rows):
  pr=row._tr.get_or_add_trPr();pr.append(OxmlElement('w:cantSplit'))
  if ri==0:pr.append(OxmlElement('w:tblHeader'))
  for ci,c in enumerate(row.cells):
   c.width=Inches(widths[ci]);c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
   tc=c._tc.get_or_add_tcPr();bd=OxmlElement('w:tcBorders')
   for edge in ['top','left','bottom','right']:
    v=OxmlElement('w:'+edge);v.set(qn('w:val'),'single');v.set(qn('w:sz'),'4');v.set(qn('w:color'),'D9D9D9');bd.append(v)
   tc.append(bd)
   if ri==0:
    v=OxmlElement('w:shd');v.set(qn('w:fill'),'E5EDF3');tc.append(v)
   mar=OxmlElement('w:tcMar')
   for edge in ['top','bottom','left','right']:
    v=OxmlElement('w:'+edge);v.set(qn('w:w'),'75');v.set(qn('w:type'),'dxa');mar.append(v)
   tc.append(mar)
   for q in c.paragraphs:
    q.paragraph_format.space_after=Pt(1);q.paragraph_format.space_before=Pt(1);q.paragraph_format.line_spacing=1.05
    if ci==0 and len(heads)>2:q.alignment=1
    for r in q.runs:r.font.size=Pt(9);r.bold=ri==0
 q=p(d,'');q.paragraph_format.space_after=Pt(0);q.paragraph_format.space_before=Pt(0);q.paragraph_format.line_spacing=Pt(4);q.add_run().font.size=Pt(1)
 return t

def new(kind,register):
 d=Document();s=d.sections[0];s.page_width=Inches(8.27);s.page_height=Inches(11.69);s.top_margin=Inches(.65);s.bottom_margin=Inches(.68);s.left_margin=s.right_margin=Inches(.71)
 for name in ['Normal','Title','Subtitle','Heading 1','Heading 2','Caption','Header','Footer']:
  st=d.styles[name];st.font.name='Malgun Gothic';st._element.get_or_add_rPr().rFonts.set(qn('w:eastAsia'),'Malgun Gothic');st.font.color.rgb=RGBColor(0,0,0)
 for st in d.styles:
  for bd in list(st.element.iter(qn('w:pBdr'))):bd.getparent().remove(bd)
 d.styles['Normal'].font.size=Pt(10);d.styles['Normal'].paragraph_format.space_after=Pt(5);d.styles['Normal'].paragraph_format.line_spacing=1.1
 d.styles['Title'].font.size=Pt(25);d.styles['Heading 1'].font.size=Pt(17);d.styles['Heading 2'].font.size=Pt(12);d.styles['Caption'].font.size=Pt(8)
 s.header.paragraphs[0].text='VESTIGIA   /   '+kind+' UI 명세서   /   초안 v0.2';s.header.paragraphs[0].style='Caption'
 f=s.footer.paragraphs[0];f.alignment=2;f.add_run('2026 09 26   ·   ');fld=OxmlElement('w:fldSimple');fld.set(qn('w:instr'),'PAGE');f._p.append(fld)
 d.core_properties.title='VESTIGIA '+kind+' UI 명세서';d.core_properties.author='VESTIGIA 프로젝트'
 d.add_heading('VESTIGIA '+kind+' UI 명세서',0)
 p(d,'화면 구조와 플레이어 조작 및 동작 정의','Subtitle')
 p(d,'초안 v0.2   2026년 9월 26일   대상 기획·개발·아트')
 p(d,'화면의 번호와 요소 정의, 조작별 동작을 연결한 구현 검토용 문서다. 화면별로 무엇을 표시하고, 어떤 입력을 받으며, 처리 후 어디로 돌아가는지 정의한다. 연출은 표시 순서와 완료 조건을 기준으로 기술한다.')
 d.add_heading('문서 읽는 법',2)
 p(d,'B는 전투, I는 가방 화면 ID다. 예를 들어 B04-03은 B04 화면의 03번 요소다. 같은 화면 안의 선택 전·후는 상태로 구분한다. 이미지의 숫자는 아래 표와 다음 페이지의 조작 표에서 동일하게 사용한다.')
 p(d,'[화면]은 와이어프레임·연결 관찰, [기획]은 시스템 규칙, [연출]은 타임라인 요구사항, [제안]은 초안의 보완안이다. 미정 또는 자료 간 차이는 [확인 필요]로 표시했다. 여러 근거를 합친 화면은 각 절의 근거를 함께 읽는다.')
 table(d,['화면 ID','화면 또는 상태','주요 역할'],register,[.75,2.1,4.0])
 q=p(d,'근거  ','Caption');link(q,'Figma 와이어프레임',BASE+('1-245' if kind=='전투' else '189-7023'));q.add_run('  /  ');link(q,'연출 타임라인 v1.2.0',TL)
 p(d,'기획서 약칭은 Waredo_2.0_전투, 캐릭터, 시간대_전환, 가방_유물의 각 시스템_기획서.md를 뜻한다. 요소 번호 뒤의 절 번호로 해당 규칙을 찾는다.','Caption')
 p(d,'Figma는 9월 25일 읽기 전용으로 화면과 연결을 조회했다. 타임라인은 9월 26일 확인했다. 시스템 규칙은 프로젝트의 system-spec/확정 로컬 사본 기준이다. 실제 게임 실행 검증은 포함하지 않는다. 원본 화면은 수정하지 않았다.','Caption')
 return d

def refs(d,node,tl,systems):
 q=p(d,'근거  ','Caption')
 if node:link(q,'화면 원본',BASE+node.replace(':','-'));q.add_run('  /  ')
 if tl:link(q,tl,TL);q.add_run('  /  ')
 q.add_run(systems)

def annotate(node,sid,marks):
 im=Image.open(E/(node.replace(':','-')+'.png')).convert('RGB');dr=ImageDraw.Draw(im);font=ImageFont.truetype('C:/Windows/Fonts/malgunbd.ttf',25)
 for n,x,y,tx,ty in marks:
  dr.line([(x,y),(tx,ty)],fill='white',width=7);dr.line([(x,y),(tx,ty)],fill='#C04C16',width=3)
  dr.ellipse((tx-4,ty-4,tx+4,ty+4),fill='#C04C16')
  dr.ellipse((x-25,y-25,x+25,y+25),fill='#A7350C',outline='white',width=3)
  dr.text((x,y-2),str(n).zfill(2),font=font,fill='white',anchor='mm')
 fn=OUT/(sid+'.png');im.save(fn);return fn

